import * as yargs from 'yargs'
import { usage } from './usage'
import { epilogue } from './epilogue'
import { clean } from './command/clean'
import { init } from './command/init'
import { build } from './command/build'
import { run } from './command/run'
import { pack } from './command/pack'
import { install } from './command/install'
import { download } from './command/download'
import { transform } from './command/transform'
import { auth } from './command/auth'
import { moveToApp } from './command/move-to-app'
import { explain } from './command/explain'
import { satisfies } from 'semver'
import { logger } from './logger'
import pkg from '../package.json'
import { dependencies } from './command/dependencies'

try {
    yargs
        .check(() => {
            const neededVersion = pkg['engines']['node']
            if (!satisfies(process.version, neededVersion)) {
                logger.error(`now-sdk requires node version to be ${neededVersion}`)
                process.exit(1)
            }
            return true
        })
        .usage(usage)
        .option('debug', {
            describe: 'Print debug output',
            alias: 'd',
            default: false,
            type: 'boolean',
        })
        .command(auth)
        .command(init)
        .command(download)
        .command(build)
        .command(install)
        .command(dependencies)
        .command(transform)
        .command('run [script]', false, run)
        .command(clean)
        .command(pack)
        .command(explain)
        .command('move', false, moveToApp)
        .demandCommand()
        .middleware(async (argv) => {
            if (argv.debug) {
                logger.setLevel('debug')
                logger.debug('Debug logging enabled')
            }
        })
        .epilogue(epilogue)
        .strictCommands()
        .help()
        .updateStrings({
            'Positionals:': 'Parameters:',
        })
        .alias('h', 'help')
        .alias('v', 'version')
        .scriptName('now-sdk').argv
} catch (error) {
    logger.error(error)
}
